      var tag = c.querySelector('.reel__letter');
      tl.fromTo(c.querySelector('.reel__media'), { clipPath: 'inset(100% 0% 0% 0%)' }, { clipPath: 'inset(0% 0% 0% 0%)', duration: 1.3, ease: 'expo.out', clearProps: 'clipPath' }, at)
        .fromTo(c.querySelector('video'), { scale: 1.28 }, { scale: 1, duration: 1.8, ease: 'expo.out', clearProps: 'scale,transform' }, at)
        .fromTo(c.querySelectorAll('.reel__no, .reel__title'), { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: 0.9, stagger: 0.05, ease: 'power3.out', clearProps: 'transform' }, at + 0.45);
      if (tag) {
        tl.fromTo(tag, { opacity: 0, scaleY: 0.15 }, { opacity: 1, scaleY: 1, duration: 0.7, ease: 'power3.out', transformOrigin: '50% 0%' }, at + 0.55)
          .fromTo(tag, { rotation: i % 2 ? 16 : -16 }, { rotation: 0, duration: 2.2, ease: 'elastic.out(1, 0.3)', transformOrigin: '50% 0%' }, at + 0.55);
      }
